 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # A vertical 5-bar carries a colored tile at its right-hand end;
    # extend that tile periodically along the bar.
    c = 0
    while c < w:
        if not any(g[r][c] == 5 for r in range(h)):
            c += 1
            continue
        # Use each contiguous vertical run of 5s.
        r = 0
        while r < h:
            if g[r][c] != 5:
                r += 1
                continue
            a = r
            while r < h and g[r][c] == 5:
                r += 1
            b = r
            if c + 1 >= w:
                continue
            # Locate a colored seed band immediately right of the bar.
            seed_rows = [rr for rr in range(a, b) if g[rr][c+1] != 0 and g[rr][c+1] != 5]
            if not seed_rows:
                continue
            # Require a contiguous colored seed block and use its rows as a tile.
            lo, hi = min(seed_rows), max(seed_rows) + 1
            if any(g[rr][c+1] in (0, 5) for rr in range(lo, hi)):
                continue
            # The row-pattern extends right through its contiguous nonzero cells.
            endc = c + 1
            while endc < w and any(g[rr][endc] not in (0, 5) for rr in range(lo, hi)):
                endc += 1
            width_end = endc
            tile = [g[rr][c+1:width_end] for rr in range(lo, hi)]
            for rr in range(a, b):
                pat = tile[(rr - lo) % len(tile)]
                g[rr][c+1:width_end] = pat[:]

    # A horizontal 5-bar can similarly border a vertical color sample below it.
    r = 0
    while r < h:
        if g[r].count(5) < 2:
            r += 1
            continue
        # Find contiguous horizontal runs of 5s.
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            left = c
            while c < w and g[r][c] == 5:
                c += 1
            right = c
            if right - left < 2 or r + 1 >= h:
                continue
            # A vertical color sample immediately below the left edge.
            sample = []
            rr = r + 1
            while rr < h and g[rr][left] not in (0, 5):
                sample.append(g[rr][left])
                rr += 1
            if not sample:
                continue
