    for c in range(w - 1):
        r = 0
        while r < h:
            if g[r][c] != 5:
                r += 1
                continue
            a = r
            while r < h and g[r][c] == 5:
                r += 1
            b = r
            seed_rows = [rr for rr in range(a, b) if g[rr][c + 1] not in (0, 5)]
            if not seed_rows:
                continue
            lo, hi = min(seed_rows), max(seed_rows) + 1
            # Tile is the contiguous colored block extending right of the bar.
            end = c + 1
            while end < w and any(g[rr][end] not in (0, 5) for rr in range(lo, hi)):
                end += 1
            tile = [g[rr][c + 1:end] for rr in range(lo, hi)]
            if not tile or any(not row for row in tile):
                continue
            for rr in range(a, b):
                g[rr][c + 1:end] = tile[(rr - lo) % len(tile)][:]

    # Transposed case: a horizontal 5-bar has a vertical color sample
    # beneath its left end; repeat each sample color across the bar's width.
    for r in range(h - 1):
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            left = c
